<script setup lang="ts">
/**
 * Where a number comes from, in one small chip (swarm audit 2026-10-30: sample and simulated values were
 * shown as if they were the user's own). Click it for one plain sentence.
 *
 *   account   — your own account data from the server (default: no chip is rendered)
 *   paper     — your paper money (real prices, no real money)
 *   sample    — demo data that is not yours (sample files, another account's demo book)
 *   simulated — generated by a model (Monte Carlo, replay), not observed
 *   pending   — not computed yet (shown with "—", the field stays)
 */
import { computed, ref } from 'vue'

const props = withDefaults(defineProps<{ source?: 'account' | 'paper' | 'sample' | 'simulated' | 'pending'; note?: string }>(), {
  source: 'account', note: '',
})
const open = ref(false)
const META = {
  account: { label: '', line: '' },
  paper: { label: 'Paper', line: 'Paper money: real market prices, no real money.' },
  sample: { label: 'Sample', line: 'Sample data so the page is not empty: it is not your account.' },
  simulated: { label: 'Simulated', line: 'Generated by a model, not observed in the market.' },
  pending: { label: 'Not computed', line: 'Not computed yet: the field stays so you know it exists.' },
} as const
const meta = computed(() => META[props.source])
</script>

<template>
  <span v-if="source !== 'account'" class="src" :class="source">
    <button type="button" class="chip" :aria-expanded="open" @click.stop="open = !open">{{ meta.label }}</button>
    <span v-if="open" class="why" role="note">{{ note || meta.line }}</span>
  </span>
</template>

<style scoped>
.src { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 0.3rem; vertical-align: middle; }
.chip { all: unset; cursor: pointer; font-size: 0.6rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase;
  padding: 0.12rem 0.4rem; border-radius: 999px; border: 1px solid currentColor; line-height: 1.3; }
.chip:focus-visible { outline: 2px solid var(--text-white); outline-offset: 2px; }
.paper .chip { color: var(--primary-blue); }
.sample .chip { color: var(--warning-orange); }
.simulated .chip { color: #b48cff; }
.pending .chip { color: var(--text-gray); }
.why { font-size: 0.7rem; color: var(--text-light-gray); }
</style>
